const incidentId = '754cb5b5-6dce-479d-bafa-310f2b0374aa';
const userId = '9030a1cd-64a3-44fb-93c0-125cd11440c3';

const testUrl = 'https://no-1.rayvn.global/restapi/incidents/' + incidentId + '/periodic/files/' + userId;

const rayvn_config = global.get('rayvn_config');

msg.url = testUrl;
msg.headers = {
    'Authorization': 'Bearer ' + rayvn_config.api_key
};

node.log('Fetching periodic/files');

return msg;

const buffer = msg.payload;

let result = {
    status: msg.statusCode,
    size: buffer ? buffer.length : 0
};

if (buffer) {
    try {
        const json = JSON.parse(buffer.toString());
        // Finn objektet med invalid.wasos.no
        const wasosEntry = json.find(item => item.url && item.url.includes('wasos'));
        result.wasosEntry = wasosEntry;
    } catch (e) {
        result.content = buffer.toString().substring(0, 3000);
    }
}

msg.payload = result;
return msg;
